  if (!isoDate) return null;
  const diff = new Date(isoDate + 'T00:00:00') - new Date(TODAY + 'T00:00:00');
  return Math.round(diff / 86400000);
}

function getExpiringQuals(staffList, thresholdDays = 30) {
  const results = [];
  for (const member of staffList) {
